let shaderProgram; // Variable to store the shader program
const numOperationsMax = 30; // Maximum number of shader operations allowed

// Array of names for base transformation operations
const baseOperationNames = [
    "affine",
    "reflectX",
    "reflectY",
    "invertCircle",
    "rotate",
    "tileTriangle",
    "mandelbrot",
    "julia"
];

// Array of names for color and effect operations
const effectOperationNames = [
    "colorShift",
    "add",
    "multiply",
    "divide",
    "mod",
    "abs",
    "sin",
    "cos",
    "tan",
    "noise",
    "gradientX",
    "gradientY",
    "gradientRadial",
    "gradientAngular",
    "mixColors",
    "contrast",
    "saturation",
    "brightness",
    "gamma"
];

const MAX_ATTEMPTS = 1000; // Maximum number of attempts to generate a valid set of operations
const MIN_TRANSFORMS = 5; // Minimum number of transform operations in the pipeline
const MIN_COLORS = 5;     // Minimum number of color operations in the pipeline
const MIN_NOISE_GRADIENTS = 5; // Minimum number of noise and gradient operations in the pipeline
const MAX_PER_OP = 3;      // Maximum allowed number of repetitions for any operation

let delayBeforeLoop = 100; // Delay before shader loop starts (in milliseconds)

// Array of color operations that can have a secondary input value
const operation2Allowed = [
    "colorShift",
    "divide",
    "abs",
    "sin",
    "cos"
];

let operations = []; // Array to hold the current shader operations

// Vertex shader source code
const vertShader = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = vec4(aPosition, 1.0);
}
`;

// Fragment shader source code
const fragShader = `
precision highp float;

varying vec2 vTexCoord;

uniform vec2 u_resolution;
uniform int u_numOperations;
uniform int u_operationTypes[30];
uniform float u_params1[30];
uniform float u_params2[30];
uniform float u_params3[30];
uniform float u_params4[30];

// Function to generate a pseudo-random noise value
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = smoothstep(0.0,1.0,fract(st));
    float a = fract(sin(dot(i, vec2(12.9898, 78.233))) * 43758.5453);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(12.9898, 78.233))) * 43758.5453);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Function to determine if an operation type is a transform operation
bool isTransformOperation(int opType) {
    // 0..7 => base transforms
    return (opType >= 0 && opType <= 7);
}

// Function to determine if an operation type is a color operation
bool isColorOperation(int opType) {
    // 8.. => color/effect operations
    return (opType >= 8);
}

// Function to apply a transform operation to UV coordinates
vec2 applyUVOperation(int type, vec2 uv, float param1, float param2, float param3, float param4) {
    float aspect = u_resolution.x / u_resolution.y;
    float scaleFactor = 3.0;
    vec2 mappedUV = uv * scaleFactor;

    if (type == 0) {
        // affine
        float a = param1; 
        float b = param2; 
        float c = param3; 
        float d = param4; 
        // Simple 2D linear transform
        // Using matrix [a 0; 0 b] plus translation [c, d] 
        // If you need a more complex affine, add the cross-term here.
        return vec2(uv.x * a + c, uv.y * b + d);

    } else if (type == 1) {
        // reflectX
        return vec2(-uv.x * param1, uv.y * param2);

    } else if (type == 2) {
        // reflectY
        return vec2(uv.x * param1, -uv.y * param2);

    } else if (type == 3) {
        // invertCircle
        float dist = length(uv);
        float modifiedParam = 0.001 + (1.0 - param1) * 0.999;
        // The smaller (modifiedParam) => the stronger the inversion
        return uv / (dist * dist * modifiedParam);

    } else if (type == 4) {
        // rotate
        float angle = atan(uv.y, uv.x) + param1;
        float radius = length(uv);
        return vec2(radius * cos(angle), radius * sin(angle));

    } else if (type == 5) {
        // tileTriangle
        float triX = mod(mappedUV.x, 1.0);
        float triY = mod(mappedUV.y, 0.8660254);
        vec2 offset = vec2(0.0);
        if (triY > 0.57735 * triX) {
            if (triY > -0.57735 * triX + 0.8660254) {
                // no offset
            } else {
                offset = vec2(0.5 * param1, 0.288675 * param2);
            }
        } else {
            offset = vec2(0.5 * param1, -0.288675 * param2);
        }
        return (vec2(mappedUV.x + offset.x, mappedUV.y + offset.y)) / scaleFactor;

    } else if (type == 6) {
        // mandelbrot
        // param1 => iteration factor in [0..1], so let's do a smooth integer count up to ~25..125
        // param2 => scale factor
        // param3 => offset.x
        // param4 => offset.y

        float maxIter = floor(25.0 + param1 * 100.0 + 0.5); // make it an integer
        float iterCount = 0.0;

        vec2 c = (uv * param2) + vec2(param3, param4);
        vec2 z = vec2(0.0);

        for (int i = 0; i < 300; i++) {
            if (float(i) >= maxIter) break;
            if (dot(z, z) > 4.0) break;
            z = vec2(z.x*z.x - z.y*z.y + c.x, 2.0*z.x*z.y + c.y);
            iterCount += 1.0;
        }

        // Blend 'uv' and 'z' based on how many iterations occurred
        // This reduces flicker because it won't abruptly jump to z
        float ratio = iterCount / maxIter;
        return mix(uv, z, ratio * 0.9) / param2;

    } else if (type == 7) {
        // julia
        // param1 => iteration factor in [0..1] => ~25..125
        // param2 => scale factor
        // param3 => c.x
        // param4 => c.y

        float maxIter = floor(25.0 + param1 * 100.0 + 0.5);
        float iterCount = 0.0;

        vec2 z = uv * param2;
        vec2 c = vec2(param3, param4);

        for (int i = 0; i < 300; i++) {
            if (float(i) >= maxIter) break;
            if (dot(z, z) > 4.0) break;
            z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
            iterCount += 1.0;
        }

        float ratio = iterCount / maxIter;
        // Here we do a subtle mix between the original uv*param2 and the final z
        return mix(uv * param2, z, ratio);
    }

    // Fallback (should never hit):
    return uv;
}

// Function to apply a color operation to the current color
vec3 applyColorOperation(int type, vec2 uv, vec3 currentColor,
                        float param1, float param2, float param3, float param4)
{
    float aspect = u_resolution.x / u_resolution.y;
    float scaleFactor = 3.0;
    vec2 mappedUV = uv * scaleFactor;

    // We'll build a 'finalColor' and then blend it with 'currentColor'
    // so that each operation does not completely override previous ops.
    vec3 finalColor = currentColor; // default

    if (type == 8) {
        // colorShift
        // Instead of overriding, let's produce a new color and then we'll blend
        float r = fract(currentColor.r + param1);
        float g = fract(currentColor.g + param2);
        float b = fract(currentColor.b + param3);
        finalColor = vec3(r, g, b);

    } else if (type == 9) {
        // add
        finalColor = currentColor + vec3(param1, param2, param3);

    } else if (type == 10) {
        // multiply
        finalColor = currentColor * vec3(param1, param2, param3);

    } else if (type == 11) {
        // divide
        // Avoid division by zero
        float x = (abs(param1) < 0.00001) ? 1.0 : param1;
        float y = (abs(param2) < 0.00001) ? 1.0 : param2;
        float z = (abs(param3) < 0.00001) ? 1.0 : param3;
        finalColor = vec3(currentColor.r / x, currentColor.g / y, currentColor.b / z);

    } else if (type == 12) {
        // mod
        // We'll clamp to avoid negative values going weird
        finalColor = vec3(
            mod(currentColor.r, max(0.001, param1)),
            mod(currentColor.g, max(0.001, param2)),
            mod(currentColor.b, max(0.001, param3))
        );

    } else if (type == 13) {
        // abs
        // Taking abs but let's keep some factor from p1, p2, p3
        vec3 scaled = vec3(param1, param2, param3);
        finalColor = abs(currentColor) * scaled;

    } else if (type == 14) {
        // sin
        finalColor = vec3(
            sin(currentColor.r * param1),
            sin(currentColor.g * param2),
            sin(currentColor.b * param3)
        );

    } else if (type == 15) {
        // cos
        finalColor = vec3(
            cos(currentColor.r * param1),
            cos(currentColor.g * param2),
            cos(currentColor.b * param3)
        );

    } else if (type == 16) {
        // tan
        finalColor = vec3(
            tan(currentColor.r * param1),
            tan(currentColor.g * param2),
            tan(currentColor.b * param3)
        );

    } else if (type == 17) {
        // noise
        // We blend the new noise color with currentColor
        vec3 noiseValue = vec3(noise(mappedUV * param1),
                               noise(mappedUV * param2),
                               noise(mappedUV * param3));
        finalColor = mix(currentColor, noiseValue, clamp(param4, 0.0, 1.0));

    } else if (type == 18) {
        // gradientX
        float gradientValue = mappedUV.x * param1;
        vec3 gradColor = vec3(gradientValue);
        finalColor = mix(currentColor, gradColor, clamp(param4, 0.0, 1.0));

    } else if (type == 19) {
        // gradientY
        float gradientValue = mappedUV.y * param1;
        vec3 gradColor = vec3(gradientValue);
        finalColor = mix(currentColor, gradColor, clamp(param4, 0.0, 1.0));

    } else if (type == 20) {
        // gradientRadial
        float r = length(mappedUV);
        vec3 gradColor = vec3(r * param1, r * param2, r * param3);
        finalColor = mix(currentColor, gradColor, clamp(param4, 0.0, 1.0));

    } else if (type == 21) {
        // gradientAngular
        float angle = atan(mappedUV.y, mappedUV.x);
        vec3 gradColor = vec3(angle * param1, angle * param2, angle * param3);
        finalColor = mix(currentColor, gradColor, clamp(param4, 0.0, 1.0));

    } else if (type == 22) {
        // mixColors
        vec3 cMix = vec3(param1, param2, param3);
        finalColor = mix(currentColor, cMix, clamp(param4, 0.0, 1.0));

    } else if (type == 23) {
        // contrast
        float contrast = param1;
        vec3 avgColor = vec3(0.2126, 0.7152, 0.0722);
        finalColor = ((currentColor - avgColor) * contrast + avgColor);

    } else if (type == 24) {
        // saturation
        float sat = param1;
        vec3 grayScale = vec3(dot(currentColor, vec3(0.299, 0.587, 0.114)));
        finalColor = mix(grayScale, currentColor, sat);

    } else if (type == 25) {
        // brightness
        finalColor = currentColor * param1;

    } else if (type == 26) {
        // gamma
        // avoid gamma ~1 flicker => clamp param1
        float gVal = clamp(param1, 0.01, 5.0);
        finalColor = vec3(
            pow(currentColor.r, gVal),
            pow(currentColor.g, gVal),
            pow(currentColor.b, gVal)
        );
    }

    // ---- Final Blending Step ----
    // We do a second mix to ensure that param4 always controls how strongly
    // the new finalColor overrides currentColor.
    // For color ops that already used param4, you can choose to keep or remove
    // the line below. If you want a single consistent blend factor, keep it:
    float blendFactor = 1.0; // or clamp(param4, 0.0, 1.0) if you want the same param4
                             // controlling final blend
    return mix(currentColor, finalColor, blendFactor);
}

void main() {
    // Convert from [0,1] to [-1,1]
    vec2 uv = vTexCoord * 2.0 - 1.0;
    float aspect = u_resolution.x / u_resolution.y;
    uv.x *= aspect;

    // First pass: Apply transform operations
    vec2 transformedUV = uv;
    for (int i = 0; i < 30; i++) {
        if (i >= u_numOperations) break;
        int t = u_operationTypes[i];
        if (isTransformOperation(t)) {
            transformedUV = applyUVOperation(t, transformedUV,
                                             u_params1[i], u_params2[i],
                                             u_params3[i], u_params4[i]);
        }
    }

    // Base color after transforms
    vec3 color = vec3(transformedUV, 0.0);

    // Second pass: Apply color operations
    for (int i = 0; i < 30; i++) {
        if (i >= u_numOperations) break;
        int t = u_operationTypes[i];
        if (isColorOperation(t)) {
            color = applyColorOperation(t, transformedUV, color,
                                        u_params1[i], u_params2[i],
                                        u_params3[i], u_params4[i]);
        }
    }

    gl_FragColor = vec4(color, 1.0);
}
`;

