// --- INSERTION POINT FOR startDrag, endDrag, startModalDrag, endModalDrag ---
// Function to start dragging the UI
function startDrag() {
  isDragging = true;
  let containerPos = uiContainer.position();
  dragOffsetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - containerPos.x;
  dragOffsetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - containerPos.y;
}

// Function to stop dragging the UI
function endDrag() {
  isDragging = false;
}

// Function to start dragging the modal
function startModalDrag() {
    isDragging = true;
    var containerPos = exportImportModal.position();
    dragOffsetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - containerPos.x;
    dragOffsetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - containerPos.y;
}

// Function to stop dragging the modal
function endModalDrag() {
    isDragging = false;
}

// Function to make the UI draggable
function makeUIDraggable() {
    uiHeader.mousePressed(startDrag);
    uiHeader.mouseReleased(endDrag);
}

// Sync Target Values
function syncTargetVariables() {
    targetNumOperations = operations.length;
    for(let i = 0; i < numOperationsMax; i++){
        targetOperationTypes[i] = getOperationIndex(i, operations[i].type);
        targetParams1[i] = operations[i].param1;
        targetParams2[i] = operations[i].param2;
        targetParams3[i] = operations[i].param3;
        targetParams4[i] = operations[i].param4;
    }
}

function setup() {
    pixelDensity(1); // Set initial pixel density
    initOperations();  // Initialize shader operations
    syncTargetVariables(); // Sync target values after init operations
    createUI();    // Create the UI
    updateTargetValues() // sync target values after creating ui
    initCanvas();     // Initialize the canvas
    initTargets(); // Initialize animation targets
    createExportImportModal(); // Create the export/import modal

        // Initialize operationWeights with default value of 1.0 for all operations
    baseOperationNames.concat(effectOperationNames).forEach(opName => {
        operationWeights[opName] = 1.0;
    });
}


// Function to initialize the canvas
function initCanvas() {
    if (myCanvas) {
        myCanvas.remove(); // Remove existing canvas
    }

    // Set pixel density based on AA settings
    if (aaEnabled) {
        aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
        pixelDensity(aaLevel);
    } else {
        aaLevel = 1;
        pixelDensity(1);
    }

    myCanvas = createCanvas(windowWidth, windowHeight, WEBGL); // Create a new canvas
    noStroke(); // Disable stroke on shapes
    shaderProgram = createShader(vertShader, fragShader); // Create the shader program
    loop(); // Start the render loop
}

// Initialize target values for animation
function initTargets() {
    targetNumOperations = numOperationsMax;
    currentNumOperations = numOperationsMax;

    for (let i = 0; i < numOperationsMax; i++) {
        let opType = operations[i].type;
        targetOperationTypes.push(getOperationIndex(i, opType));
        targetParams1.push(operations[i].param1);
        targetParams2.push(operations[i].param2);
        targetParams3.push(operations[i].param3);
        targetParams4.push(operations[i].param4);

        currentOperationTypes.push(getOperationIndex(i, opType));
        currentParams1.push(operations[i].param1);
        currentParams2.push(operations[i].param2);
        currentParams3.push(operations[i].param3);
        currentParams4.push(operations[i].param4);
    }
}

// Check if an operation name is a trigonometric operation
function isTrig(opName) {
    return ["sin", "cos", "tan"].includes(opName);
}

function initOperations() {
    let attempts = 0;

    // Define allowed effect operations by excluding gradient operations
    const allowedEffectOperationNames = effectOperationNames.filter(op => 
        !['gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(op)
    );

    while (attempts < MAX_ATTEMPTS) {
        operations = [];
        let brightnessCount = 0;
        let contrastCount = 0;
        let saturationCount = 0;
        let mixColorsCount = 0;
        let gammaCount = 0;
        let addCount = 0;
        let multiplyCount = 0;
        let divideCount = 0;
        let modCount = 0;
        let sinCount = 0;
        let cosCount = 0;
        let tanCount = 0;
        let noiseCount = 0;
        let transformCount = 0;

        for (let i = 0; i < numOperationsMax; i++) {
            let opName, params;

            if (i < MIN_TRANSFORMS) {
                // Ensure first MIN_TRANSFORMS operations are transforms
                opName = random(baseOperationNames);
                params = assignParametersWithStrictLimits(opName, 1.0);
                transformCount++;
            } else if (i < MIN_TRANSFORMS + MIN_COLORS) {
                // Ensure next MIN_COLORS operations are color operations excluding gradients
                const nonGradientColorOps = effectOperationNames.filter(op => 
                    !['gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(op)
                );
                // Select operation based on operationWeights
                let selectedOp = getWeightedRandom(nonGradientColorOps, nonGradientColorOps.map(op => operationWeights[op]));
                opName = selectedOp;
                params = assignParametersWithStrictLimits(opName, 1.0);
                // Increment counts based on opName
                switch(opName){
                    case 'brightness': brightnessCount++; break;
                    case 'contrast': contrastCount++; break;
                    case 'saturation': saturationCount++; break;
                    case 'mixColors': mixColorsCount++; break;
                    case 'gamma': gammaCount++; break;
                    case 'add': addCount++; break;
                    case 'multiply': multiplyCount++; break;
                    case 'divide': divideCount++; break;
                    case 'mod': modCount++; break;
                    case 'sin': sinCount++; break;
                    case 'cos': cosCount++; break;
                    case 'tan': tanCount++; break;
                    // Add more cases as needed
                }
            } else if (i < MIN_TRANSFORMS + MIN_COLORS + MIN_NOISE_GRADIENTS) {
                // Ensure next MIN_NOISE_GRADIENTS operations are noise only (exclude gradients)
                opName = 'noise';
                params = assignParametersWithStrictLimits(opName, 1.0);
                noiseCount++;
            } else {
                // For remaining operations, allow base operations and non-gradient effect operations with balanced probability
                let availableOps = [...baseOperationNames, ...allowedEffectOperationNames];
                let weights = availableOps.map(op => {
                    if (baseOperationNames.includes(op)) {
                        return operationWeights[op] * 2.0; // Transforms are important for variation
                    } else if (op === 'noise') {
                        return operationWeights[op] * 1.5; // Noise adds complexity
                    } else {
                        return operationWeights[op] * 1.0; // Regular color ops
                    }
                });
                opName = getWeightedRandom(availableOps, weights);
                params = assignParametersWithStrictLimits(opName, 1.0);
                // Increment counts based on opName
                switch(opName){
                    case 'brightness': brightnessCount++; break;
                    case 'contrast': contrastCount++; break;
                    case 'saturation': saturationCount++; break;
                    case 'mixColors': mixColorsCount++; break;
                    case 'gamma': gammaCount++; break;
                    case 'add': addCount++; break;
                    case 'multiply': multiplyCount++; break;
                    case 'divide': divideCount++; break;
                    case 'mod': modCount++; break;
                    case 'sin': sinCount++; break;
                    case 'cos': cosCount++; break;
                    case 'tan': tanCount++; break;
                    case 'noise': noiseCount++; break;
                    // Add more cases as needed
                }
            }

            // Avoid overusing certain operations
            let opCount = 0;
            for (let op of operations) {
                if (op.type === opName) opCount++;
            }
            if (opCount >= MAX_PER_OP) {
                attempts++;
                break; // Discard this pipeline and try again
            }

            operations.push({
                type: opName,
                param1: params.param1,
                param2: params.param2,
                param3: params.param3,
                param4: params.param4
            });
        }

        if (operations.length !== numOperationsMax) {
            attempts++;
            continue; // Try again if pipeline not complete
        }

        // Ensure only noise is mandatory
        operations = ensureMandatoryVariationOps(operations);

        // Validate pipeline for diversity
        if (!validatePipelineForVariation(operations) || isPurePrimaryColor(operations)) {
            attempts++;
            continue; // Try again
        }

        // If we reach here, we got a good pipeline
        break;
    }

    // Fallback if none found after MAX_ATTEMPTS
    if (operations.length === 0) {
        operations = [
            { type: "affine", param1: 1, param2: 1, param3: 0, param4: 0 },
            { type: "colorShift", param1: 0.1, param2: 0.2, param3: 0.3, param4: 0 },
            { type: "noise", param1: 1.0, param2: 0.0, param3: 0.0, param4: 0.7 }
