    }

    // Ensure we have numOperationsMax elements without gradients
    while (operations.length < numOperationsMax) {
        let op = createRandomOp(random([...baseOperationNames, ...allowedEffectOperationNames]));
        operations.push(op);
    }
}


// Function to clamp a position within the window bounds
function clampPosition(x, y, elementWidth, elementHeight) {
  let clampedX = constrain(x, 0, windowWidth - elementWidth); // Clamp X to window width
  let clampedY = constrain(y, 0, windowHeight - elementHeight); // Clamp Y to window height
  return { x: clampedX, y: clampedY }; // Return clamped position as an object
}

// Function to ensure a minimum level of complexity in the operation pipeline
function ensureComplexity(ops) {
    let hasNoise = ops.some(op => op.type === 'noise'); // Check if pipeline contains a noise operation
    let gradientCount = ops.filter(op => ['gradientX','gradientY','gradientRadial','gradientAngular'].includes(op.type)).length; // Count gradient operations
    let hasTrigOrGamma = ops.some(op => ['sin','cos','tan','gamma'].includes(op.type)); // Check if pipeline contains trig or gamma operations

    // Ensure there is at least one noise operation
    if (!hasNoise) {
        let noiseOp = createRandomOp('noise');
        noiseOp.param4 = Math.max(noiseOp.param4, 0.7); // Ensure the noise is not too weak
        ops.push(noiseOp);
    }

    // Ensure there are at least two gradient operations
    while (gradientCount < 2) {
        let gradType = Math.random() < 0.5 ? 'gradientRadial' : 'gradientAngular'; // Randomly select radial or angular gradient
        let gradOp = createRandomOp(gradType);
        gradOp.param4 = Math.max(gradOp.param4, 0.7); // Ensure the gradient is not too weak
        ops.push(gradOp);
        gradientCount++;
    }

     // Ensure there is at least one trig function or gamma operation
    if (!hasTrigOrGamma) {
        let trigOps = ['sin','cos','tan','gamma'];
        let chosen = trigOps[Math.floor(Math.random()*trigOps.length)]; // Randomly select a trig or gamma operation
        let trigOp = createRandomOp(chosen);
        ops.push(trigOp);
    }

    // Check uniformity again after adjustments
    if (!validatePipelineForVariation(ops)) {
        let fallbackNoise = createRandomOp('noise');
        fallbackNoise.param4 = 1.0; // Ensure the fallback noise is strong
        ops.push(fallbackNoise);
    }

    return ops; // Return modified operations pipeline
}

// Function to validate if a pipeline of operations creates enough visual variation
function validatePipelineForVariation(ops) {
    const SAMPLE_COUNT = 15; // Number of sample points to use for diversity check
    let colors = []; // Array to store color values at sample points
    for (let i = 0; i < SAMPLE_COUNT; i++) {
        for (let j = 0; j < SAMPLE_COUNT; j++) {
            let u = (i / (SAMPLE_COUNT - 1)) * 2 - 1; // Map i to u [-1,1] range
            let v = (j / (SAMPLE_COUNT - 1)) * 2 - 1; // Map j to v [-1,1] range
            colors.push(evaluatePipelineAtUV(u, v, ops)); // Evaluate color at the current uv and add to array
        }
    }

    // Calculate color diversity
    let diversity = calculateColorDiversity(colors);
    return diversity > 0.1; // Return true if diversity is above the threshold
}

// Function to calculate color diversity based on a set of colors
function calculateColorDiversity(colors) {
    let distinctColors = new Set(); // Use a Set to store unique color combinations
    colors.forEach(c => {
        // Quantize colors to reduce sensitivity to minor variations
        let key = `${Math.round(c.r * 100)},${Math.round(c.g * 100)},${Math.round(c.b * 100)}`;
        distinctColors.add(key); // Add the quantized color string to set
    });
    return distinctColors.size / colors.length; // Calculate diversity as a ratio
}

// Function to determine if colors are too similar based on variance
function colorsAreTooSimilar(colors, threshold) {
    let avg = {r:0,g:0,b:0}; // Initialize average color object
    for (let c of colors) {
        avg.r += c.r; avg.g += c.g; avg.b += c.b; // Accumulate color values
    }
    avg.r /= colors.length; // Calculate average red
    avg.g /= colors.length; // Calculate average green
    avg.b /= colors.length; // Calculate average blue

    let variance = {r:0,g:0,b:0}; // Initialize variance object
    for (let c of colors) {
        variance.r += Math.pow(c.r - avg.r, 2); // Accumulate variance of red
        variance.g += Math.pow(c.g - avg.g, 2); // Accumulate variance of green
        variance.b += Math.pow(c.b - avg.b, 2); // Accumulate variance of blue
    }
    variance.r /= colors.length; // Calculate variance of red
    variance.g /= colors.length; // Calculate variance of green
    variance.b /= colors.length; // Calculate variance of blue

    let maxVar = Math.max(variance.r, variance.g, variance.b); // Find max variance

    // If max variance is below a tiny threshold, it's uniform
    return maxVar < threshold;
}


// Function to test if a given pipeline of operations results in a single color output
function isSingleColorPipeline(ops) {
    // We'll sample a few UV coordinates and see if the colors differ
    const sampleUVs = [
        { u: 0.0, v: 0.0 },
        { u: 0.5, v: 0.5 },
        { u: -0.5, v: 0.3 },
        { u: 0.2, v: -0.4 }
    ];

    var colors = sampleUVs.map(uv => {
        return evaluatePipelineAtUV(uv.u, uv.v, ops); // Get the color from each UV
    });

    // Check the variance of these colors
    return colorsAreAllSimilar(colors, 0.02); // return true if colors are similar
}

// Function to evaluate the color at a given UV coordinate by applying the pipeline
function evaluatePipelineAtUV(u, v, ops) {
    let uv = {x: u, y: v}; // Create UV object
    const aspect = windowWidth / windowHeight; // Get aspect ratio

    // Apply transform operations CPU-side
    let transformedUV = {x: uv.x * aspect, y: uv.y}; // Apply aspect ratio
    for (let op of ops) {
        if (isTransform(op.type)) {
            transformedUV = applyUVOperationCPU(op.type, transformedUV, op.param1, op.param2, op.param3, op.param4); // Apply each transform operation
        }
    }

    // Initialize color based on transformed UV
    let color = {r: transformedUV.x, g: transformedUV.y, b: 0.0}; // Initialize color based on transformed UV

    // Apply color operations CPU-side
    for (let op of ops) {
        if (isColorEffect(op.type)) {
            color = applyColorOperationCPU(op.type, transformedUV, color, op.param1, op.param2, op.param3, op.param4); // Apply each color operation
        }
    }

    // Clamp the color to [0,1] range for safety
    color.r = clampValue(color.r, 0, 1);
    color.g = clampValue(color.g, 0, 1);
    color.b = clampValue(color.b, 0, 1);

    return color; // Return the evaluated color
}

// Function to check if all colors in an array are similar
function colorsAreAllSimilar(colors, threshold) {
    // Compute average color
    var avg = {r:0,g:0,b:0};
    for (let c of colors) {
        avg.r += c.r;
        avg.g += c.g;
        avg.b += c.b;
    }
    avg.r /= colors.length;
    avg.g /= colors.length;
    avg.b /= colors.length;

    // Check max deviation
    for (let c of colors) {
        if (Math.abs(c.r - avg.r) > threshold ||
            Math.abs(c.g - avg.g) > threshold ||
            Math.abs(c.b - avg.b) > threshold) {
            return false; // Found a color not similar
        }
    }

    return true; // If no color is too far from average, return true
}

// CPU versions of operations (simplified)
function applyUVOperationCPU(opType, uv, p1, p2, p3, p4) {
    let x = uv.x; // Initialize local x
    let y = uv.y; // Initialize local y
    switch(opType) {
        case 'affine':
            // Example affine transformation matrix components
            let a = p1, b = p2, c = p3, d = p4;
            return {
                x: a * x + b * y,
                y: c * x + d * y
            };
        case 'rotate':
            let angle = p1; // In radians
            let cosA = Math.cos(angle);
            let sinA = Math.sin(angle);
            return {
                x: x * cosA - y * sinA,
                y: x * sinA + y * cosA
            };
        case 'reflectX':
            return { x: x, y: -y };
        case 'reflectY':
            return { x: -x, y: y };
        // Add more transform operations as needed
        default:
            return { x: x, y: y };
    }
}

// CPU version of color operations
function applyColorOperationCPU(type, uv, col, p1, p2, p3, p4) {
