        case "colorShift":
            // Shift colors and wrap around using frac to keep within [0,1]
            r = frac(r + p1);
            g = frac(g + p2);
            b = frac(b + p3);
            break;

        case "abs":
            // Take absolute value and scale
            r = Math.abs(r) * clampValue(p1, 0, 2);
            g = Math.abs(g) * clampValue(p2, 0, 2);
            b = Math.abs(b) * clampValue(p3, 0, 2);
            break;

        case "add":
            // Add values to color channels
            r += clampValue(p1, -1, 1);
            g += clampValue(p2, -1, 1);
            b += clampValue(p3, -1, 1);
            break;

        case "multiply":
            // Multiply color channels by parameters
            r *= clampValue(p1, 0, 2);
            g *= clampValue(p2, 0, 2);
            b *= clampValue(p3, 0, 2);
            break;

        case "divide":
