            r = p1 !== 0 ? r / clampValue(p1, 0.1, 2) : r;
            g = p2 !== 0 ? g / clampValue(p2, 0.1, 2) : g;
            b = p3 !== 0 ? b / clampValue(p3, 0.1, 2) : b;
            break;

        case "mod":
            // Modulus operation on color channels
            r = clampValue(r % clampValue(p1, 0.1, 2), 0, 1);
            g = clampValue(g % clampValue(p2, 0.1, 2), 0, 1);
            b = clampValue(b % clampValue(p3, 0.1, 2), 0, 1);
