            r = clampValue((r - 0.5) * clampValue(p1, 0.5, 1.5) + 0.5, 0, 1);
            g = clampValue((g - 0.5) * clampValue(p1, 0.5, 1.5) + 0.5, 0, 1);
            b = clampValue((b - 0.5) * clampValue(p1, 0.5, 1.5) + 0.5, 0, 1);
