            g = clampValue((g + p2) / 2, 0, 1);
            b = clampValue((b + p3) / 2, 0, 1);
            break;

        case "sin":
            // Apply sine transformation
            r = clampValue(Math.sin(r * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
            g = clampValue(Math.sin(g * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
            b = clampValue(Math.sin(b * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
            break;

        case "cos":
            // Apply cosine transformation
            r = clampValue(Math.cos(r * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
            g = clampValue(Math.cos(g * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
            b = clampValue(Math.cos(b * clampValue(p1, -Math.PI, Math.PI) + clampValue(p2, -Math.PI, Math.PI)), 0, 1);
