            r = clampValue(Math.tan(r * clampValue(p1, -Math.PI / 2, Math.PI / 2) + clampValue(p2, -Math.PI / 2, Math.PI / 2)), 0, 1);
            g = clampValue(Math.tan(g * clampValue(p1, -Math.PI / 2, Math.PI / 2) + clampValue(p2, -Math.PI / 2, Math.PI / 2)), 0, 1);
            b = clampValue(Math.tan(b * clampValue(p1, -Math.PI / 2, Math.PI / 2) + clampValue(p2, -Math.PI / 2, Math.PI / 2)), 0, 1);
