            b += clampValue(p3 * uv.x, -1, 1);
            break;

        case "gradientY":
            // Modify color based on vertical gradient
            r += clampValue(p1 * uv.y, -1, 1);
            g += clampValue(p2 * uv.y, -1, 1);
            b += clampValue(p3 * uv.y, -1, 1);
            break;

        case "gradientRadial":
            // Modify color based on radial gradient
            let radialDist = Math.sqrt(uv.x * uv.x + uv.y * uv.y);
