 */
function assignParametersWithStrictLimits(opName, transformParameter) {
    // Generate base parameters based on the operation name
    let { p1, p2, p3, p4 } = generateBaseParams(opName, transformParameter);

    // Apply stricter limits based on the specific operation
    switch (opName) {

        // ------------- MANDELBROT -------------
