        case 'julia':
            p1 = clampValue(random(0.0, 1.0), 0.0, 1.0);      // iteration factor
            p2 = clampValue(random(0.5, 2.0), 0.5, 2.0);      // scale
            p3 = clampValue(random(-2.0, 2.0), -2.0, 2.0);    // c.x
            p4 = clampValue(random(-2.0, 2.0), -2.0, 2.0);    // c.y
            break;

