function generateGammaParam() {
    let param;
    do {
        if (Math.random() < 0.5) {
            // Generate a random value in the lower range (0.5 to 0.9).
            param = random(0.5, 0.9);
        } else {
            // Generate a random value in the upper range (1.1 to 1.5).
            param = random(1.1, 1.5);
        }
    } while (isValueInBadGammaRange(param)); // Keep generating if the value is in the bad range
