function generateBaseParams(opName, transformParameter) {
    let p1, p2, p3, p4;
    switch (opName) {
        case 'invertCircle':
            p1 = random(0.05, 0.95); // Radius for the circle
            p2 = 0; // Not used
            p3 = 0; // Not used
            p4 = 0; // Not used
            break;
        case 'colorShift':
            p1 = random(-0.5, 0.5); // Red shift
            p2 = random(-0.5, 0.5); // Green shift
            p3 = random(-0.5, 0.5); // Blue shift
            p4 = 0; // Not used
            break;
        case 'add':
        case 'multiply':
        case 'divide':
            p1 = random(0.3, 1.7); // Value for operation
            p2 = random(0.3, 1.7); // Value for operation
            p3 = random(0.3, 1.7); // Value for operation
            p4 = 0; // Not used
            break;
        case 'mod':
            p1 = random(0.1, 2.0);  // Modulus value
            p2 = random(0.1, 2.0);  // Modulus value
            p3 = random(0.1, 2.0);  // Modulus value
            p4 = 0; // Not used
            break;
        case 'abs':
            p1 = random(-2.0, 2.0); // Input value
            p2 = random(-2.0, 2.0); // Input value
            p3 = random(-2.0, 2.0); // Input value
             p4 = 0; // Not used
            break;
        case 'sin':
        case 'cos':
        case 'tan':
            p1 = random(-Math.PI, Math.PI); // Angle for trigonometric function
            p2 = random(-Math.PI, Math.PI); // Angle for trigonometric function
            p3 = random(-Math.PI, Math.PI); // Angle for trigonometric function
            p4 = 0; // Not used
            break;
        case 'noise':
            p1 = random(-1.5, 1.5); // Noise parameters
            p2 = random(-1.5, 1.5); // Noise parameters
            p3 = random(-1.5, 1.5); // Noise parameters
            p4 = random(0.5, 1); // Blend factor (ensures p4 >= 0.5)
            break;
        case 'gradientX':
        case 'gradientY':
        case 'gradientRadial':
        case 'gradientAngular':
            p1 = random(-1.5, 1.5); // Gradient parameters
            p2 = random(-1.5, 1.5); // Gradient parameters
            p3 = random(-1.5, 1.5); // Gradient parameters
            p4 = random(0.5, 1); // Blend factor (ensures p4 >= 0.5)
            break;
        case 'mixColors':
            p1 = random(0.0, 2.0); // Color mixer
            p2 = random(0.0, 2.0); // Color mixer
            p3 = random(0.0, 2.0); // Color mixer
             p4 = random(0.0, 1.0); // Blend factor
            break;
        case 'contrast':
        case 'gamma':
        case 'brightness':
        case 'saturation':
             if (opName === 'gamma') {
                // Gamma parameters generated with helper function
                p1 = generateGammaParam();
            } else {
                p1 = random(0.5, 1.5); // Adjustments
            }
            p2 = 0; // Not used
            p3 = 0; // Not used
            p4 = 0; // Not used
            break;
        // Add more cases as needed for other operations
        default:
            p1 = random(-1.5, 1.5);
            p2 = random(-1.5, 1.5);
            p3 = random(-1.5, 1.5);
             p4 = random(0.0, 1.0);
    }

    return { p1, p2, p3, p4 };
}

// Flags to track rendering and animation states
let isRendering = false; // Boolean indicating whether the shader is currently rendering
let transitionEnded = false; // Boolean indicating whether the transition has ended (currently unused)
let animationStartTime; // Tracks the time when the animation started


/**
 * Main drawing function that renders the shader with the current parameters.
 * This function is called in a loop and handles the animation and rendering of the shader.
 *
 */
function draw() {
    isRendering = true; // Set the rendering flag to true

    // Check if an animation (the existing param interpolation to target) is in progress
    if (isAnimating) {
        let elapsed = millis() - animationStartTime; // ms since the animation started
        let t = elapsed / animationDuration;         // normalized time [0..1]
        t = constrain(t, 0, 1);

        // Ease in-out cubic
        if (t < 0.5) {
            t = 4.0 * t * t * t;
        } else {
            t = 1.0 - pow(-2.0 * t + 2.0, 3.0) / 2.0;
        }

        // Interpolate number of operations
        currentNumOperations = lerp(currentNumOperations, targetNumOperations, t);

        // Interpolate operation parameters
        for (let i = 0; i < numOperationsMax; i++) {
            currentParams1[i] = lerp(currentParams1[i], targetParams1[i], t);
            currentParams2[i] = lerp(currentParams2[i], targetParams2[i], t);
            currentParams3[i] = lerp(currentParams3[i], targetParams3[i], t);
            currentParams4[i] = lerp(currentParams4[i], targetParams4[i], t);
            currentOperationTypes[i] = targetOperationTypes[i];
        }

        // If done
        if (elapsed >= animationDuration) {
            isAnimating = false;
            currentNumOperations = targetNumOperations;
            for (let i = 0; i < numOperationsMax; i++) {
                currentOperationTypes[i] = targetOperationTypes[i];
                currentParams1[i] = targetParams1[i];
                currentParams2[i] = targetParams2[i];
                currentParams3[i] = targetParams3[i];
                currentParams4[i] = targetParams4[i];
            }
        }
    }

    /*************** ANIMATION MODE ****************/
    if (isAnimationModeEnabled) {
        // We pass "millis()" as the currentTime, so speeds are time-based
        updateAnimatedParameters(millis());
    }

    shader(shaderProgram); // Set the shader program

    // Determine how many operations
    let numOperations = int(currentNumOperations);
    numOperations = constrain(numOperations, 1, numOperationsMax);

    // Prepare uniform arrays
    let operationTypes = [];
    let params1 = [];
    let params2 = [];
    let params3 = [];
    let params4 = [];

    for (let i = 0; i < numOperationsMax; i++) {
        if (i < numOperations) {
            operationTypes.push(int(currentOperationTypes[i]));
            params1.push(currentParams1[i]);
            params2.push(currentParams2[i]);
            params3.push(currentParams3[i]);
            params4.push(currentParams4[i]);
        } else {
            operationTypes.push(0);
            params1.push(0.0);
            params2.push(0.0);
            params3.push(0.0);
            params4.push(0.0);
        }
    }

    // Set uniforms
    shaderProgram.setUniform("u_resolution", [width, height]);
    shaderProgram.setUniform("u_numOperations", numOperations);
    shaderProgram.setUniform("u_operationTypes", operationTypes);
    shaderProgram.setUniform("u_params1", params1);
    shaderProgram.setUniform("u_params2", params2);
    shaderProgram.setUniform("u_params3", params3);
    shaderProgram.setUniform("u_params4", params4);

    // Draw fullscreen quad
    beginShape(TRIANGLES);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, -1, 0, 1, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, 1, 0, 0, 1);
    endShape();

    isRendering = false; // Reset rendering flag
}

