/**
 * Adjusts the operation weights based on the feedback score.
 * Higher scores increase the weights of operations used in the last randomization,
 * making similar good outputs more likely. Lower scores decrease their weights,
 * reducing the likelihood of similar bad outputs.
 *
 * @param {number} score - The feedback score from 1 to 10.
 */
function adjustOperationWeights(score) {
    // After receiving multiple feedback sessions, the effect should be stronger.
    // Introduce a scaling factor that grows with the number of ratings given (ratingCount).

    let factor;
    if (score > 5) {
        // Increase weights for operations used in last randomization
        // Original factor: 1 + ((score - 5) / 5)
        // Make it stronger and more noticeable:
        factor = 1 + ((score - 5) / 5) * 3; // Triples the original effect for positive feedback
    } else if (score < 5) {
        // Decrease weights for operations used in last randomization
        // Original factor: 1 - ((5 - score) / 5)
        // Make it stronger:
        factor = 1 - ((5 - score) / 5) * 3;
        // Ensure factor doesn't go below 0.1 to avoid negative or zero weights
        if (factor < 0.1) factor = 0.1;
    } else {
        // score == 5 means neutral, do nothing
        console.log("Neutral score received. No weight adjustments.");
        return;
    }

    // Now scale factor further by ratingCount to ensure the effect becomes more pronounced over time
    // For example, every 20 ratings, the factor gets doubled again.
    factor *= (1 + ratingCount / 20.0);

    if (score > 5) {
        let uniqueOps = [...new Set(lastRandomizedOperations)];
        uniqueOps.forEach(opType => {
            operationWeights[opType] *= factor;
            operationWeights[opType] = constrainWeight(operationWeights[opType]);
        });
        console.log("Increased weights for operations:", uniqueOps, "Factor:", factor);
    } else if (score < 5) {
        var uniqueOps = [...new Set(lastRandomizedOperations)];
        uniqueOps.forEach(opType => {
            operationWeights[opType] *= factor;
            operationWeights[opType] = constrainWeight(operationWeights[opType]);
        });
        console.log("Decreased weights for operations:", uniqueOps, "Factor:", factor);
    }
}

/**
 * Constrains the operation weight within defined minimum and maximum bounds.
 *
 * @param {number} weight - The current weight of the operation.
 * @returns {number} - The constrained weight.
 */
function constrainWeight(weight) {
    const MIN_WEIGHT = 0.1;
    const MAX_WEIGHT = 10.0;
    return Math.min(Math.max(weight, MIN_WEIGHT), MAX_WEIGHT);
}

