 * Handles parsing the JSON, updating variables, UI elements, and error handling.
 */
    function importSettings() {
        try {
            var jsonString = importTextArea.value();
            const importData = JSON.parse(jsonString);

            if (importData) {
              targetNumOperations = importData.numOperations;
                targetOperationTypes = importData.operationTypes.slice();
                targetParams1 = importData.params1.slice();
                targetParams2 = importData.params2.slice();
                targetParams3 = importData.params3.slice();
                targetParams4 = importData.params4.slice();

                aaEnabled = importData.aaEnabled;
                aaLevel = importData.aaLevel;

              // Rebuild the operations array based on the order it appears in the file
                operations = new Array(numOperationsMax); // Initialize operations array with correct length
              for(let i=0; i<numOperationsMax; i++) {
                    let typeName;
                    if (i === 0 || importData.operationTypes[i] < baseOperationNames.length) {
                        typeName = baseOperationNames[importData.operationTypes[i]]
                    } else {
                         typeName = effectOperationNames[importData.operationTypes[i] - baseOperationNames.length];
                    }

                    var op = importData.operations.find(op => op.index === i);

                  if (op) {
                    operations[i] = {
                      type: typeName,
                      param1: targetParams1[i],
                      param2: targetParams2[i],
                      param3: targetParams3[i],
                      param4: targetParams4[i],
