                numOperationsSlider.value(targetNumOperations);

                 // Directly set the dropdown options using the DOM element
                for (let i = 0; i < numOperationsMax; i++) {
                    var op = operations[i];
                    if (op) {
                         let dropdown = operationTypeDropdowns[i];
                         // Use the operations array to set the dropdown using the string values,
                        let optionToSelect = Array.from(dropdown.elt.options).find(option => option.value === op.type);
                        if (optionToSelect) {
                            dropdown.elt.value = op.type;
                            // *** NEW: Sync targetOperationTypes with *current UI dropdown state* using the string type values:
                           targetOperationTypes[i] = getOperationIndex(i, dropdown.elt.value);

                        }
                         param1Sliders[i].value(op.param1);
                        param2Sliders[i].value(op.param2);
                        param3Sliders[i].value(op.param3);
