/****************** Animation Randomization ******************/
function initParamAnimationData() {
    // Clear any existing data
    paramAnimationData = [];

    for (let i = 0; i < numOperationsMax; i++) {
        // We'll prepare 4 parameter-channels: p1, p2, p3, p4
        // Each channel has:
        //   speed: how fast it changes (reduced for slower animation)
        //   offset: a phase offset (so they don't all start at the same angle)
        //   amplitude: how far it can deviate from the target param

        paramAnimationData[i] = {
            p1: {
                speed: random(0.0002, 0.0005),        // Slower speed
                offset: random(TWO_PI),           // Random phase offset
                amplitude: random(0.2, 1.0)       // Amplitude remains the same
            },
            p2: {
                speed: random(0.0002, 0.0005),        // Slower speed
                offset: random(TWO_PI),           // Random phase offset
                amplitude: random(0.2, 1.0)       // Amplitude remains the same
            },
            p3: {
                speed: random(0.0002, 0.0005),        // Slower speed
                offset: random(TWO_PI),           // Random phase offset
                amplitude: random(0.2, 1.0)       // Amplitude remains the same
            },
            p4: {
                speed: random(0.0002, 0.0005),        // Slower speed
                offset: random(TWO_PI),           // Random phase offset
                amplitude: random(0.2, 1.0)       // Amplitude remains the same
            }
        };
    }
}


/****************** Smooth Animation ******************/
function updateAnimatedParameters(currentTime) {
    // We'll update each parameter in the "currentParamsX" arrays
    // so that they fluctuate around their respective targetParamsX
    // without abruptly changing operation types.

    // First, compute how much time has passed since last update
    let dt = (currentTime - lastAnimationUpdateTime) / 1000.0; // convert ms to sec
    lastAnimationUpdateTime = currentTime; // store for next frame

    // Only animate the ones up to the currentNumOperations
    for (let i = 0; i < numOperationsMax; i++) {
        if (i >= currentNumOperations) break; // ignore inactive ops

        // Short references for the 4 animation channels
        let animData = paramAnimationData[i];

        // Animate param1
        let wave1 = sin(animData.p1.speed * currentTime + animData.p1.offset);
        currentParams1[i] = targetParams1[i] + animData.p1.amplitude * wave1;

        // Animate param2
        let wave2 = sin(animData.p2.speed * currentTime + animData.p2.offset);
        currentParams2[i] = targetParams2[i] + animData.p2.amplitude * wave2;

        // Animate param3
        let wave3 = sin(animData.p3.speed * currentTime + animData.p3.offset);
        currentParams3[i] = targetParams3[i] + animData.p3.amplitude * wave3;

        // Animate param4
        let wave4 = sin(animData.p4.speed * currentTime + animData.p4.offset);
        currentParams4[i] = targetParams4[i] + animData.p4.amplitude * wave4;
    }
}
