// Flag to check if updates are pending
let pendingUpdates = false;

/**
 * Updates the target values based on the current UI state.
 * Reads the values of sliders and dropdowns and stores them into target variables.
 * Sets the animation flag for smooth transition, also updates labels in ui.
 */
function updateTargetValues() {
    // 1) Read the slider for total operations
    targetNumOperations = int(numOperationsSlider.value());
    targetNumOperations = constrain(targetNumOperations, 1, numOperationsMax);

    // 2) For each operation slot:
    for (let i = 0; i < numOperationsMax; i++) {
        // Read the dropdown selection
        var typeName = operationTypeDropdowns[i].value();

        // If we're at slot > 0 and experimental mode is OFF, disallow base ops
        if (i > 0 && !isExperimentalModeEnabled && baseOperationNames.includes(typeName)) {
            // Force a switch to any effect operation
            typeName = random(effectOperationNames);
            operationTypeDropdowns[i].selected(typeName);
        }

        // Convert the string to an integer index for the shader
        if (i === 0) {
            // Base operation index
            targetOperationTypes[i] = baseOperationNames.indexOf(typeName);
        } else {
            // Effect operation index (offset by baseOperationNames.length)
            targetOperationTypes[i] = effectOperationNames.indexOf(typeName) + baseOperationNames.length;
        }

        // 3) Read the user’s 4 param sliders
        targetParams1[i] = param1Sliders[i].value();
        targetParams2[i] = param2Sliders[i].value();
        targetParams3[i] = param3Sliders[i].value();
        targetParams4[i] = param4Sliders[i].value();

        // 4) Also update the 'operations[i]' object
        operations[i].type   = typeName;
        operations[i].param1 = targetParams1[i];
        operations[i].param2 = targetParams2[i];
        operations[i].param3 = targetParams3[i];
        operations[i].param4 = targetParams4[i];

        // Show/hide param sliders for the chosen operation
        updateParamVisibility(i);
    }

    // 5) Update the UI state
    updateUIState(targetNumOperations);
    numOpLabel.html('Number of Operations: ' + targetNumOperations);

    // 6) Start a smooth param interpolation from current to target
    animationStartTime = millis();
    isAnimating = true;
    loop();
}

