/**
 * Helper function to get the correct index for an operation.
 * @param {number} index - The index of the operation.
 * @param {string} typeName - The name of the operation type.
 * @returns {number} The correct index for operation names.
 */
function getOperationIndex(slotIndex, typeName) {
    // slotIndex == 0 -> pick index from baseOperationNames
    // slotIndex >= 1 -> pick index from effectOperationNames (then add baseOperationNames.length)
    if (slotIndex === 0) {
        // Must be one of the 8 transforms (0..7)
        return baseOperationNames.indexOf(typeName);
    } else {
        // Must be a color operation => find index in effect array, offset by base array’s length
        return effectOperationNames.indexOf(typeName) + baseOperationNames.length;
    }
}

/**
 * Checks if the current set of operations results in a predominantly primary color output.
 * @param {Array} ops - An array of operation objects.
 * @returns {boolean} True if the output is close to a primary or neutral color, false otherwise.
 */
function isPurePrimaryColor(ops) {
    var SAMPLE_COUNT = 10;
    var colors = [];
    for (let i = 0; i < SAMPLE_COUNT; i++) {
        for (let j = 0; j < SAMPLE_COUNT; j++) {
            var u = (i / (SAMPLE_COUNT - 1)) * 2 - 1;
            var v = (j / (SAMPLE_COUNT - 1)) * 2 - 1;
            colors.push(evaluatePipelineAtUV(u, v, ops));
        }
    }

    var avg = {r:0, g:0, b:0};
    for (let c of colors) {
        avg.r += c.r;
        avg.g += c.g;
        avg.b += c.b;
    }
    avg.r /= colors.length;
    avg.g /= colors.length;
    avg.b /= colors.length;

    // Define primary and neutral colors
    let candidates = [
        {r:0, g:0, b:0},       // black
        {r:1, g:1, b:1},       // white
        {r:1, g:0, b:0},       // red
        {r:0, g:1, b:0},       // green
        {r:0, g:0, b:1}        // blue
    ];

    let threshold = 0.05;
    for (let c of candidates) {
        var dist = Math.sqrt(
            Math.pow(avg.r - c.r, 2) +
            Math.pow(avg.g - c.g, 2) +
            Math.pow(avg.b - c.b, 2)
        );
        if (dist < threshold) {
            return true;
        }
    }

    return false;
}

/**
 * Adjusts operation parameters to enhance variety if the output is too uniform.
 * Increases the magnitude of the 'param4' for noise and gradient operations.
 * @param {Array} ops - An array of operation objects.
 * @returns {Array} The adjusted array of operation objects.
 */
function postGenerationAdjustmentIfUniform(ops) {
    let adjusted = false;
    for (let op of ops) {
        if (op.type === 'noise' || (op.type && op.type.indexOf('gradient') !== -1)) {
            op.param4 = Math.max(op.param4, 0.9);
            adjusted = true;
        }
    }
    if (adjusted && validatePipelineForVariation(ops)) return ops;

    // Insert a strong noise op:
    var noiseOp = createRandomOp('noise');
    noiseOp.param4 = 1.0;
    ops.push(noiseOp);

    if (!validatePipelineForVariation(ops)) {
        // Add another noise if still uniform
        let extraNoise = createRandomOp('noise');
        extraNoise.param4 = 1.0;
        ops.push(extraNoise);
    }

    return ops;
}

/**
 * Adds failsafe adjustments to operation set to avoid uniform output.
 * Filters out duplicate gamma, brightness, and saturation operations, then adds a noise.
 * @param {Array} ops - An array of operation objects.
 * @returns {Array} The adjusted array of operation objects.
 */
function finalFailSafeAdjustmentIfUniform(ops) {
    var gammaCount = 0, brightCount = 0, satCount = 0;
    ops = ops.filter(op => {
        if (op.type === 'gamma') {
            gammaCount++;
            return gammaCount <= 1;
        }
        if (op.type === 'brightness') {
            brightCount++;
            return brightCount <= 1;
        }
        if (op.type === 'saturation') {
            satCount++;
            return satCount <= 1;
        }
        return true;
    });

    let failSafeNoise = {
        type: 'noise',
        param1: 1.0,
        param2: 1.0,
        param3: 1.0,
        param4: 1.0
    };
    ops.push(failSafeNoise);

    if (!validatePipelineForVariation(ops)) {
        let extraGrad = createRandomOp('gradientRadial');
        extraGrad.param4 = 1.0;
        ops.push(extraGrad);
    }

    return ops;
}

/**
 * Applies a hardcore fallback strategy if the output is still uniform.
 * Removes flattening operations (add, divide, mod), adds multiple noises, gradients and trig functions.
 * @param {Array} ops - An array of operation objects.
 * @returns {Array} The adjusted array of operation objects.
 */
function hardcoreFallbackIfUniform(ops) {
    // Remove flattening linear ops: too many mod, add, divide
    let filtered = [];
    var addCount=0, divideCount=0, modCount=0;
    for (let op of ops) {
        if (op.type === 'add') { addCount++; if (addCount>1) continue; }
        if (op.type === 'divide') { divideCount++; if (divideCount>1) continue; }
        if (op.type === 'mod') { modCount++; if (modCount>1) continue; }
        filtered.push(op);
    }
    ops = filtered;

    // Add multiple strong noise and gradient ops:
    for (let i=0; i<2; i++) {
        var noiseOp = createRandomOp('noise');
        noiseOp.param4 = 1.0;
        ops.push(noiseOp);
    }
    for (let i=0; i<2; i++) {
        var gradType = Math.random()<0.5?'gradientRadial':'gradientAngular';
        var gradOp = createRandomOp(gradType);
        gradOp.param4=1.0;
        ops.push(gradOp);
    }

    // Add trig ops:
    var trigOps = ['sin','cos','tan'];
    for (let i=0; i<2; i++) {
        var chosen = trigOps[Math.floor(Math.random()*trigOps.length)];
        var trigOp = createRandomOp(chosen);
        ops.push(trigOp);
    }

    // Check and if still uniform, add a final gamma or brightness with a subtle parameter:
    if (!validatePipelineForVariation(ops)) {
        let gammaOp = createRandomOp('gamma');
        gammaOp.param1 = 1.0; // Neutral gamma
        ops.push(gammaOp);
    }

    return ops;
}

/**
 * Ensures that there's at least one noise operation present for variation.
 * If no noise op is present, inserts one at a valid random position.
 * @param {Array} ops - An array of operation objects.
 * @returns {Array} The adjusted array of operation objects.
 */
function ensureMandatoryVariationOps(ops) {
    var hasNoise = ops.some(op => op.type === 'noise');

    if (!hasNoise) {
        var noiseOp = createRandomOp('noise');
        noiseOp.param4 = Math.max(noiseOp.param4, 0.7);
        // Insert at a random position after transforms and initial color ops
        let insertIndex = MIN_TRANSFORMS + MIN_COLORS + Math.floor(Math.random() * (ops.length - MIN_TRANSFORMS - MIN_COLORS));
        ops.splice(insertIndex, 0, noiseOp);
        if (ops.length > numOperationsMax) ops.pop();
    } else {
        // Ensure existing noise ops have sufficient param4
        for (let op of ops) {
            if (op.type === 'noise') {
                op.param4 = Math.max(op.param4, 0.7);
                break;
            }
        }
    }

    return ops;
}

/**
 * Creates a new random operation object with given name.
 * @param {string} name - The name of the operation type.
 * @returns {object} A new operation object with random parameters.
 */
function createRandomOp(name) {
    if (!name || (!baseOperationNames.includes(name) && !effectOperationNames.includes(name))) {
        console.warn("createRandomOp called without a valid operation name. Assigning default 'affine'.");
        name = 'affine';
    }
    let p = assignParametersWithStrictLimits(name, 1.0);
    return {
        type: name,
        param1: p.param1,
        param2: p.param2,
        param3: p.param3,
        param4: p.param4
    };
}

/**
 * Updates the shader and redraws the canvas.
 * Triggers a loop and then a noLoop to refresh the canvas.
 */
function updateShader() {
    loop();
    setTimeout(() => noLoop(), 10);
}

/**
 * Updates the visual state of the UI based on the number of active operations.
 * Enables or disables controls based on whether they are part of the active set of operations.
 * @param {number} numActiveOperations - The number of active operations.
 */
function updateUIState(numActiveOperations) {
    for (let i = 0; i < numOperationsMax; i++) {

        // --- Rebuild the dropdown options based on Experimental Mode ---
        var dropdown = operationTypeDropdowns[i];

        // Clear existing options:
        dropdown.elt.innerHTML = '';

        // If we are at slot 0 OR experimental mode is ON, we can use base ops:
        if (i === 0 || isExperimentalModeEnabled) {
            baseOperationNames.forEach(name => dropdown.option(name));
        }
        // Always allow effect ops:
        effectOperationNames.forEach(name => dropdown.option(name));

        // Re-select the operation currently in 'operations[i].type'
        // (it might have changed in handleExperimentalModeChange)
        var op = operations[i].type;
        // Safety check: if 'op' is not in baseOperationNames or effectOperationNames, fallback:
        if (!baseOperationNames.includes(op) && !effectOperationNames.includes(op)) {
            op = 'affine'; // fallback
            operations[i].type = op;
        }
        dropdown.selected(op);

        // Now visually enable/disable the container and sliders
        if (i < numActiveOperations) {
            operationContainers[i].style('background', 'rgba(50, 50, 50, 0.8)');
            dropdown.removeAttribute('disabled');
            param1Sliders[i].removeAttribute('disabled');
            param2Sliders[i].removeAttribute('disabled');
            param3Sliders[i].removeAttribute('disabled');
            param4Sliders[i].removeAttribute('disabled');
        } else {
            operationContainers[i].style('background', 'rgba(100, 100, 100, 0.3)');
            dropdown.attribute('disabled', '');
            param1Sliders[i].attribute('disabled', '');
            param2Sliders[i].attribute('disabled', '');
            param3Sliders[i].attribute('disabled', '');
            param4Sliders[i].attribute('disabled', '');
        }
    }
}

/**
 * Helper function to check if an opName is a transform operation.
 * @param {string} opName - The name of the operation.
 * @returns {boolean} True if the operation is a transform, false otherwise.
 */
function isTransform(opName) {
    return baseOperationNames.includes(opName);
}

/**
 * Helper function to check if an opName is a color effect operation.
 * @param {string} opName - The name of the operation.
 * @returns {boolean} True if the operation is a color effect (not noise or gradients), false otherwise.
 */
function isColorEffect(opName) {
    return effectOperationNames.includes(opName) && !['noise', 'gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(opName);
}

/**
 * Helper function to check if an opName is a gradient or noise operation.
 * @param {string} opName - The name of the operation.
 * @returns {boolean} True if the operation is noise or a gradient, false otherwise.
 */
function isGradientOrNoise(opName) {
    return ['noise', 'gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(opName);
}

/**
 * Function for weighted random selection from an array.
 * Utilizes the global operationWeights to influence selection probabilities.
 *
 * @param {Array} items - An array of items to select from.
 * @param {Array} weights - An array of weights corresponding to the items.
 * @returns {*} A randomly selected item based on the weights.
 */
function getWeightedRandom(items, weights) {
    let totalWeight = weights.reduce((acc, weight) => acc + weight, 0);
    if (totalWeight === 0) {
        console.warn("Total weight is zero in getWeightedRandom. Selecting a random item without weighting.");
        return random(items);
    }
    let randomNumber = Math.random() * totalWeight;
    for (let i = 0; i < items.length; i++) {
        randomNumber -= weights[i];
        if (randomNumber <= 0) {
            return items[i];
        }
    }
    return items[items.length - 1];
}


/**
 * Checks for known bad parameter ranges for gradientRadial operations.
 * @param {number} p1 - The first parameter of the gradient.
 * @param {number} p2 - The second parameter of the gradient.
 * @param {number} p3 - The third parameter of the gradient.
 * @returns {boolean} True if the parameters match a bad range, false otherwise.
 */
function isBadGradientRadial(p1, p2, p3) {
    // Check previously known bad ranges
    const badRanges = [
        {
            min1: 0.95, max1: 1.25,
            min2: 1.15, max2: 1.55,
            min3: 1.2, max3: 1.6
        },
        {
            min1: 1.3, max1: 1.6,
            min2: 0.7, max2: 1.2,
            min3: 1.5, max3: 2
        },
        {
            min1: 0.5, max1: 1.0,
            min2: 1.1, max2: 1.6,
            min3: 0.4, max3: 1.0
        },
        {
            min1: 1.3, max1: 1.7,
            min2: 1.5, max2: 2,
            min3: 0.6, max3: 1.0
        }
    ];

    for (const range of badRanges) {
        if (p1 >= range.min1 && p1 <= range.max1 &&
            p2 >= range.min2 && p2 <= range.max2 &&
            p3 >= range.min3 && p3 <= range.max3) {
            return true;
        }
    }

    return false;
}

/**
 * Checks if a combination of parameters for a gradient or noise operation results in a bad result
 * i.e. not enough variation, flat or too dark/bright.
 * @param {string} opName - The name of the operation.
 * @param {number} p1 - The first parameter of the operation.
 * @param {number} p2 - The second parameter of the operation.
 * @param {number} p3 - The third parameter of the operation.
 * @param {number} p4 - The fourth parameter of the operation.
 * @returns {boolean} True if the combination of parameters is bad, false otherwise.
 */
function isBadGradientCombination(opName, p1, p2, p3, p4) {
    // This function checks for known bad combos for various gradient/noise ops.
    // We can add conditions here for other gradient ops if needed.

    if (opName === 'gradientRadial') {
        // Use the existing radial checks
        if (isBadGradientRadial(p1, p2, p3)) return true;
    }

    // For gradientAngular, gradientX, gradientY, noise,
    // we can impose certain conditions to avoid flat, black/yellow looks.
    // For instance:
    if (opName === 'gradientAngular') {
        // If params are too uniform or angle leads to flat pattern, re-check:
        // Arbitrary heuristic: avoid all three params being too close to each other near certain multiples.
        if ((abs(p1 - p2) < 0.05 && abs(p2 - p3) < 0.05) && (p4 < 0.2)) return true;
    }

    if (opName === 'gradientX' || opName === 'gradientY') {
        // Avoid zero or near-zero param4 for gradients that blend poorly.
        if (p4 < 0.1) return true;
    }

    if (opName === 'noise') {
        // Avoid overly small param4 causing too subtle or stark patterns:
        if (p4 < 0.15) return true;
    }

    // Add further checks as patterns emerge.

    return false;
}

/**
 * Clamps a value between a minimum and a maximum.
 * @param {number} value - The value to clamp.
 * @param {number} min - The minimum allowed value.
 * @param {number} max - The maximum allowed value.
 * @returns {number} The clamped value.
 */
function clampValue(value, min, max){
    return Math.min(Math.max(value, min), max);
}

/**
 * Checks if a value is close to an integer.
 * @param {number} value - The value to check.
 * @param {number} tolerance - The tolerance to use for the check.
 * @returns {boolean} True if the value is close to an integer, false otherwise.
 */
function isValueCloseToInteger(value, tolerance = 0.1) {
  return Math.abs(value - Math.round(value)) < tolerance;
}

